const item = $input.first().json;
const body = item.body ?? item;
const staticData = $getWorkflowStaticData('global');
staticData.pollCount = 0;
const id = 'mock-' + Math.random().toString(36).slice(2, 10);
staticData.jobId = id;
staticData.productUrl = String(body.productUrl ?? '');
staticData.createdAt = new Date().toISOString();
return [{ json: { ok: true, data: { id, status: 'QUEUED', productUrl: staticData.productUrl, language: body.language ?? 'hinglish', voice: body.voice ?? 'hi-IN-SwaraNeural', visualStyle: body.visualStyle ?? 'premium_dark', durationSeconds: Number(body.durationSeconds ?? 15), createdAt: staticData.createdAt, mock: true } } }];

const staticData = $getWorkflowStaticData('global');
staticData.pollCount = (staticData.pollCount ?? 0) + 1;
const n = staticData.pollCount;
const jobId = staticData.jobId ?? 'mock-unknown';
const STAGES = [
  { key: 'url_validation', label: 'URL validation' },
  { key: 'product_extraction', label: 'Product extraction' },
  { key: 'product_research', label: 'Product research' },
  { key: 'fact_verification', label: 'Fact verification' },
  { key: 'media_analysis', label: 'Media analysis' },
  { key: 'compliance_review', label: 'Compliance review' },
  { key: 'creative_planning', label: 'Creative planning' },
  { key: 'script_generation', label: 'Script generation' },
  { key: 'voiceover_generation', label: 'Voiceover generation' },
  { key: 'storyboard_generation', label: 'Storyboard generation' },
  { key: 'ai_visual_generation', label: 'AI visual generation' },
  { key: 'ai_video_generation', label: 'AI video generation' },
  { key: 'editing_rendering', label: 'Editing and rendering' },
  { key: 'quality_assurance', label: 'Quality assurance' },
  { key: 'final_delivery', label: 'Final delivery' }
];
const PLAN = [
  { status: 'QUEUED', done: 0 },
  { status: 'RESEARCHING', done: 5 },
  { status: 'PLANNING', done: 8 },
  { status: 'GENERATING_ASSETS', done: 11 },
  { status: 'RENDERING', done: 13 },
  { status: 'COMPLETED', done: 15 }
];
const step = PLAN[Math.min(n - 1, PLAN.length - 1)];
const stages = STAGES.map((s, i) => ({
  stageKey: s.key,
  key: s.key,
  label: s.label,
  status: i < step.done ? 'succeeded' : (i === step.done && step.done < 15 ? 'running' : 'pending')
}));
return [{ json: { ok: true, data: { id: jobId, status: step.status, productUrl: staticData.productUrl ?? '', poll: n, progress: { done: step.done, total: STAGES.length }, stages, mock: true, note: 'Mock backend — no real video is generated. The downloadUrl in the main workflow response is illustrative only.' } } }];
